import { and, eq, gt, sql } from "drizzle-orm";
import { db } from "@/db";
import { robotAudio } from "@/db/schema";
import { uuidSchema } from "@/lib/validation";
import { RobotApiError, authenticateRobot, robotErrorResponse } from "@/server/robot/api";

/**
 * GET /api/robot/audio/[id] — the speech generated by /api/robot/talk.
 * Only the robot that asked can download it, and only until it expires (10 minutes).
 */
export async function GET(request: Request, { params }: RouteContext<"/api/robot/audio/[id]">) {
  try {
    const robot = await authenticateRobot(request);
    const { id } = await params;
    if (!uuidSchema.safeParse(id).success) throw new RobotApiError(404, "NOT_FOUND", "Ses bulunamadı.");

    const [audio] = await db
      .select({ data: robotAudio.data, contentType: robotAudio.contentType })
      .from(robotAudio)
      .where(
        and(eq(robotAudio.id, id), eq(robotAudio.robotId, robot.id), gt(robotAudio.expiresAt, sql`now()`)),
      );
    if (!audio) throw new RobotApiError(404, "NOT_FOUND", "Ses bulunamadı veya süresi doldu.");

    return new Response(new Uint8Array(audio.data), {
      headers: {
        "Content-Type": audio.contentType,
        "Content-Length": String(audio.data.length),
        "Cache-Control": "no-store",
      },
    });
  } catch (error) {
    return robotErrorResponse(error);
  }
}
